import functools
from typing import Any, Dict, List


def retry(times, exceptions):
    """Decorator factory: re-run the decorated function when it raises one of `exceptions`."""
    pass


# ---------------------------------------------------------------------------
# Provided — keep this. The tests call run_scenario, which decorates a scripted
# flaky function with your retry, calls it, and reports what happened.
# ---------------------------------------------------------------------------
ERRORS = {cls.__name__: cls for cls in (ConnectionError, TimeoutError, OSError, ValueError, KeyError, RuntimeError)}


def run_scenario(fail_times: int, error: str, times: int, retry_on: List[str], calls: int) -> Dict[str, Any]:
    state = {"attempts": 0}

    def read_sensor(device, *, port):
        """Read one value from a flaky device."""
        state["attempts"] += 1
        if state["attempts"] <= fail_times:
            raise ERRORS[error](f"attempt {state['attempts']}")
        return "ok"

    wrapped = retry(times=times, exceptions=tuple(ERRORS[name] for name in retry_on))(read_sensor)
    outcomes = []
    for _ in range(calls):
        state["attempts"] = 0  # each call fails its first fail_times attempts
        try:
            outcomes.append({"returned": wrapped("sensor-1", port=7), "attempts": state["attempts"]})
        except Exception as err:
            outcomes.append({"raised": f"{type(err).__name__}: {err}", "attempts": state["attempts"]})
    return {"name": wrapped.__name__, "doc": wrapped.__doc__, "calls": outcomes}
